**Missing:**
- RGB values > 255 (should error, currently doesn't)
- RGB values < 0
- Invalid hex length (e.g., `"#12345"`)

```go
func TestHandleColor_HexInvalidLength(t *testing.T) {
    body := bytes.NewBufferString(`{"input":"#12345","from":"hex","to":"rgb"}`)
    req := httptest.NewRequest("POST", "/api/convert/color", body)
    w := httptest.NewRecorder()
    HandleColor(w, req)
    if w.Code != http.StatusBadRequest { t.Error("expected 400 for invalid hex length") }
}

func TestHandleColor_RGBOverflow(t *testing.T) {
    // Currently passes 256 as valid - should fail
    body := bytes.NewBufferString(`{"input":"rgb(256,0,0)","from":"rgb","to":"hex"}`)
    req := httptest.NewRequest("POST", "/api/convert/color", body)
    w := httptest.NewRecorder()
    HandleColor(w, req)
    // Current behavior: produces "#ff0000" - arguably incorrect for RGB spec
}
```

