**Missing:**
- Length boundary: `<=0` falls back to 16
- Length boundary: `>128` caps at 128
- Each char-set flag produces characters from that set

```go
func TestHandlePassword_LengthCapping(t *testing.T) {
    tests := []struct {
        length   int
        expected int
    }{
        {0, 16},    // falls back to default
        {-1, 16},   // falls back to default  
        {129, 128}, // caps at max
        {200, 128}, // caps at max
    }
    for _, tt := range tests {
        body := bytes.NewBufferString(fmt.Sprintf(`{"length":%d,"upper":false,"digits":false,"symbols":false}`, tt.length))
        req := httptest.NewRequest("POST", "/api/password/generate", body)
        w := httptest.NewRecorder()
        HandlePassword(w, req)
        var resp map[string]string
        json.Unmarshal(w.Body.Bytes(), &resp)
        if len(resp["output"]) != tt.expected {
            t.Errorf("length=%d: expected %d, got %d", tt.length, tt.expected, len(resp["output"]))
        }
    }
}

func TestHandlePassword_CharSets(t *testing.T) {
    // Only lowercase: output should match `[a-z]`
    body := bytes.NewBufferString(`{"length":50,"upper":false,"digits":false,"symbols":false}`)
    req := httptest.NewRequest("POST", "/api/password/generate", body)
    w := httptest.NewRecorder()
    HandlePassword(w, req)
    matched, _ := regexp.MatchString(`^[a-z]+$`, w.Body.String())
    if !matched { t.Error("expected only lowercase chars") }
}
```

