**Missing:**
- decodeJWTPart padding logic (2, 3 chars needs different padding)
- URL-safe base64 replacement (-→+, _→/)
- Invalid JWT parts that fail base64 decode

```go
func TestDecodeJWTPart_Padding(t *testing.T) {
    // Test unexported via exported HandleJWT
    // Valid JWT with 2-char padding needed
    body := bytes.NewBufferString(`{"input":"eyJhbGciOiJIUzI1NiJ9.e30. signature"}`)
    req := httptest.NewRequest("POST", "/api/jwt/decode", body)
    w := httptest.NewRecorder()
    HandleJWT(w, req)
    if w.Code != http.StatusOK { t.Errorf("expected 200, got %d", w.Code) }
}

func TestHandleJWT_InvalidBase64(t *testing.T) {
    body := bytes.NewBufferString(`{"input":"!!!.!!!."}`)
    req := httptest.NewRequest("POST", "/api/jwt/decode", body)
    w := httptest.NewRecorder()
    HandleJWT(w, req)
    if w.Code != http.StatusBadRequest { t.Error("expected 400 for invalid JWT") }
}
```

