**Missing:**
- Invalid timezone string (falls back to local without error)
- Millisecond vs second timestamp auto-detection

```go
func TestHandleTimestamp_InvalidTimezone(t *testing.T) {
    body := bytes.NewBufferString(`{"input":"1234567890","to":"date","timezone":"Invalid/Zone"}`)
    req := httptest.NewRequest("POST", "/api/convert/timestamp", body)
    w := httptest.NewRecorder()
    HandleTimestamp(w, req)
    // Current: returns date in local timezone, no error - arguably should warn
}

func TestHandleTimestamp_Milliseconds(t *testing.T) {
    body := bytes.NewBufferString(`{"input":"12345678901234","to":"date"}`)
    req := httptest.NewRequest("POST", "/api/convert/timestamp", body)
    w := httptest.NewRecorder()
    HandleTimestamp(w, req)
    // Should auto-detect ms and convert correctly
}

func TestHandleTimestamp_InvalidDateFormat(t *testing.T) {
    body := bytes.NewBufferString(`{"input":"not-a-date","to":"timestamp"}`)
    req := httptest.NewRequest("POST", "/api/convert/timestamp", body)
    w := httptest.NewRecorder()
    HandleTimestamp(w, req)
    if w.Code != http.StatusBadRequest { t.Error("expected 400 for invalid date") }
}
```

